insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-180', 'pt', null, 'Assinale a alternativa em que a reescrita de "Apesar de a fila estar longa, o atendimento foi rápido" mantém o sentido e a correção gramatical.', '["Embora a fila estivesse longa, o atendimento foi rápido.","Como a fila estava longa, o atendimento foi rápido.","Porque a fila estava longa, o atendimento foi rápido.","A fila estava longa, portanto o atendimento foi rápido.","Se a fila estivesse longa, o atendimento seria rápido."]'::jsonb, 0, '"Apesar de" e "embora" expressam concessão. As demais introduzem causa, conclusão ou condição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-181', 'pt', null, 'Assinale a alternativa em que a frase está correta quanto ao uso dos porquês.', '["Ninguém sabe o porquê de tanta demora.","Ninguém sabe o por que de tanta demora.","Porquê a fila está tão longa?","A fila está longa por quê faltam profissionais.","Você não veio porque?"]'::jsonb, 0, '"Porquê" substantivado leva acento e vem antecedido de artigo. Em perguntas, "por que"; em respostas, "porque"; no fim de frase, "por quê".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-182', 'pt', null, 'Assinale a alternativa em que o termo destacado é um pronome relativo.', '["Este é o setor onde trabalho há dez anos.","Onde você deixou os exames?","Não sei onde fica o laboratório.","Quero que você venha amanhã.","Que dia cansativo!"]'::jsonb, 0, '"Onde" retoma "o setor" (= no qual) e introduz oração adjetiva: pronome relativo. Nas demais, é advérbio interrogativo, conjunção integrante ou determinante exclamativo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-183', 'pt', null, 'Assinale a alternativa em que o "se" é partícula apassivadora.', '["Realizaram-se três cirurgias no turno da manhã.","Precisa-se de enfermeiros com experiência.","O paciente se queixou de dor.","Se chover, a campanha será adiada.","Não sei se ela virá."]'::jsonb, 0, 'Verbo transitivo direto + se = voz passiva sintética (três cirurgias foram realizadas).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-184', 'pt', null, 'Assinale a frase em que o emprego de "mal" ou "mau" está correto.', '["Mal chegou ao plantão, foi chamada para uma emergência.","O mal atendimento gerou reclamações.","Ele é um mal exemplo para a equipe.","O paciente passou mau a noite toda.","Houve um mau-entendido na passagem de plantão."]'::jsonb, 0, '"Mal" pode ser conjunção temporal (= assim que), advérbio ou substantivo; "mau" é adjetivo (mau atendimento, mau exemplo). O correto é "passou mal" e "mal-entendido".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-185', 'pt', null, 'Assinale a alternativa em que há erro de concordância.', '["Segue anexo os documentos solicitados pela auditoria.","Seguem anexos os documentos solicitados pela auditoria.","Os documentos seguem anexos ao processo.","Seguem em anexo os documentos solicitados.","As planilhas seguem anexas ao relatório."]'::jsonb, 0, '"Anexo" é adjetivo e concorda com o substantivo: "Seguem anexos os documentos". A locução "em anexo" é invariável.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-186', 'pt', null, 'Assinale a alternativa em que o termo destacado exerce a função de aposto.', '["O coordenador, profissional experiente, conduziu a reunião.","Coordenador, a reunião já vai começar.","O coordenador experiente conduziu a reunião.","A reunião foi conduzida pelo coordenador.","O coordenador parecia experiente."]'::jsonb, 0, 'Aposto explica ou especifica um termo anterior. Em "Coordenador, ..." há vocativo; nas demais, adjunto adnominal, agente da passiva e predicativo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-187', 'pt', null, 'Assinale a alternativa em que a palavra "como" estabelece relação de causa.', '["Como o paciente estava em jejum, o exame foi realizado.","Fiz o curativo como a enfermeira orientou.","Ela trabalha como técnica de enfermagem há dez anos.","Como você está hoje?","A dor era forte como uma pontada."]'::jsonb, 0, '"Como" anteposto à oração principal, com o sentido de "porque", é causal. Nas demais: conformidade, qualidade/função, interrogação e comparação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-188', 'pt', null, 'Assinale a alternativa em que o verbo "assistir" está empregado com o sentido de "prestar assistência", corretamente regido.', '["A equipe de enfermagem assistiu o paciente durante toda a noite.","A equipe de enfermagem assistiu ao paciente durante toda a noite.","Os alunos assistiram o filme sobre biossegurança.","O direito ao descanso assiste o trabalhador.","Os familiares assistiram a reunião com a equipe."]'::jsonb, 0, 'Assistir (ajudar, prestar assistência) é transitivo direto: assistiu o paciente. Assistir (ver) e assistir (caber, pertencer) pedem "a".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-189', 'pt', null, 'Assinale a alternativa em que o termo destacado é complemento nominal.', '["A obediência às normas é obrigatória.","O uniforme da enfermeira estava limpo.","A sala de espera estava cheia.","O livro de registros sumiu.","A caneta azul ficou na mesa."]'::jsonb, 0, '"Às normas" completa o sentido do substantivo abstrato "obediência" (obedecer às normas). Nos demais, há adjuntos adnominais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-190', 'pt', null, 'Assinale a alternativa em que a palavra destacada foi formada por derivação parassintética.', '["entristecer","infelizmente","desleal","girassol","pontapé"]'::jsonb, 0, 'Na parassíntese, prefixo e sufixo são acrescentados ao mesmo tempo (en- + triste + -ecer). Infelizmente (prefixo e sufixo, mas existe "infeliz"): prefixal e sufixal. Girassol e pontapé: composição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-191', 'pt', null, 'Assinale a alternativa em que todas as palavras são formadas por composição por justaposição.', '["guarda-chuva, girassol, passatempo","fidalgo, planalto, aguardente","infelizmente, desleal, entristecer","boteco, cine, moto","tique-taque, zunzum, miau"]'::jsonb, 0, 'Justaposição: os radicais se unem sem perda fonética. Fidalgo, planalto e aguardente são aglutinação; cine e moto, redução; tique-taque e miau, onomatopeia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-192', 'pt', null, 'Assinale a alternativa em que a frase está correta quanto ao uso de "onde" e "aonde".', '["Aonde você levou os pacientes?","Aonde fica o almoxarifado?","Onde você vai depois do plantão?","Não sei aonde guardei os exames.","A cidade aonde moro tem dois hospitais."]'::jsonb, 0, '"Aonde" (= a que lugar) acompanha verbos que indicam movimento, como ir e levar. "Onde" indica o lugar em que algo está ou acontece.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-193', 'pt', null, 'Na frase "O sol, a chuva, o vento: nada impedia a equipe de fazer as visitas", o termo "nada" funciona como:', '["aposto resumitivo, que sintetiza os elementos enumerados.","vocativo.","adjunto adverbial de negação.","objeto direto do verbo impedir.","predicativo do sujeito."]'::jsonb, 0, 'O pronome indefinido "nada" sintetiza os termos enumerados antes dos dois-pontos: é o chamado aposto resumitivo (ou recapitulativo).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-194', 'pt', null, 'Considere o período: "Notei que o paciente precisava da medicação que estava na farmácia." Sobre as duas ocorrências de "que", é correto afirmar:', '["a primeira é conjunção integrante, introduzindo oração substantiva objetiva direta; a segunda é pronome relativo, retomando \"medicação\".","ambas são conjunções integrantes.","ambas são pronomes relativos.","a primeira é pronome relativo e a segunda, conjunção integrante.","a primeira é conjunção causal e a segunda, partícula expletiva."]'::jsonb, 0, '"Notei [que o paciente precisava...]": oração que completa o verbo. "medicação [que estava na farmácia]": oração adjetiva.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-195', 'pt', null, 'Assinale a alternativa em que o termo destacado foi empregado em sentido conotativo.', '["A equipe abraçou a causa da vacinação no bairro.","A mãe abraçou o filho após a alta.","O técnico abraçou o colega na despedida.","As crianças se abraçaram no pátio.","O avô abraçou a neta no aniversário."]'::jsonb, 0, '"Abraçar a causa" significa aderir, apoiar: sentido figurado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-196', 'pt', null, 'Leia as asserções:
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-197', 'pt', null, 'Relacione os mecanismos de textualidade aos exemplos.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-198', 'pt', null, 'Na frase "Os profissionais relataram episódios frequentes durante o plantão", assinale a alternativa que contém um substantivo seguido de adjetivo.', '["episódios frequentes","Os profissionais","relataram episódios","durante o plantão","profissionais relataram"]'::jsonb, 0, '"Episódios" é substantivo e "frequentes", adjetivo que o qualifica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-199', 'pt', null, 'No trecho "Os recursos disponíveis para a campanha eram escassos", o antônimo da palavra "escassos" é:', '["abundantes","insuficientes","raros","limitados","parcos"]'::jsonb, 0, 'Escasso = em pequena quantidade; o antônimo é abundante, farto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-200', 'pt', null, 'Na frase "Os pacientes que chegaram cedo foram atendidos primeiro", a oração destacada "que chegaram cedo" classifica-se como:', '["oração subordinada adjetiva restritiva.","oração subordinada adjetiva explicativa.","oração subordinada substantiva objetiva direta.","oração subordinada adverbial temporal.","oração coordenada sindética explicativa."]'::jsonb, 0, 'Sem vírgulas, a oração restringe o grupo: apenas os pacientes que chegaram cedo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-001', 'sus', null, 'Segundo o art. 196 da Constituição Federal de 1988, a saúde é:', '["direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e ao acesso universal e igualitário às ações e serviços.","direito dos contribuintes da previdência social e dever do Estado.","dever exclusivo da família, cabendo ao Estado apenas ações complementares.","direito de todos, sendo o acesso gratuito restrito aos comprovadamente carentes.","dever dos municípios, cabendo à União apenas a fiscalização."]'::jsonb, 0, 'Texto literal do art. 196 da CF/88: universalidade e igualdade de acesso, sem vínculo com contribuição previdenciária.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-002', 'sus', null, 'De acordo com o art. 198 da CF/88, é diretriz das ações e serviços públicos de saúde:', '["a participação da comunidade.","a centralização das ações na esfera federal.","a prioridade para as atividades assistenciais em detrimento das preventivas.","a direção compartilhada entre os entes em cada esfera de governo.","o atendimento restrito à atenção básica."]'::jsonb, 0, 'Diretrizes do art. 198: descentralização, com direção ÚNICA em cada esfera; atendimento integral, com prioridade para as atividades preventivas, sem prejuízo das assistenciais; e participação da comunidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-003', 'sus', null, 'Conforme a Lei nº 8.142/1990, a Conferência de Saúde:', '["reunir-se-á a cada quatro anos, com a representação dos vários segmentos sociais, para avaliar a situação de saúde e propor diretrizes para a formulação da política de saúde.","reunir-se-á a cada dois anos, convocada exclusivamente pelo Conselho de Saúde.","tem caráter permanente e deliberativo, reunindo-se mensalmente.","é composta exclusivamente por gestores e prestadores de serviço.","é convocada apenas pelo Ministério Público."]'::jsonb, 0, 'Conferência: a cada 4 anos, convocada pelo Poder Executivo ou, extraordinariamente, por ela ou pelo Conselho. O caráter permanente e deliberativo é do Conselho de Saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-004', 'sus', null, 'Segundo a Lei nº 8.142/1990, a representação dos usuários nos Conselhos de Saúde e Conferências será:', '["paritária em relação ao conjunto dos demais segmentos.","equivalente a um terço do total de membros.","minoritária, para garantir a governabilidade do gestor.","definida livremente pelo gestor municipal.","igual apenas à representação dos prestadores privados."]'::jsonb, 0, 'Art. 1º, §4º: usuários = 50% (paridade com o conjunto dos demais segmentos: governo, prestadores e trabalhadores).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-005', 'sus', null, 'Sobre a participação da iniciativa privada no SUS, é correto afirmar que:', '["as instituições privadas podem participar de forma complementar, tendo preferência as entidades filantrópicas e as sem fins lucrativos.","é vedada qualquer participação de instituições privadas no SUS.","as empresas com fins lucrativos têm preferência na contratação.","é livre a participação direta de empresas ou capitais estrangeiros na assistência à saúde.","a contratação dispensa contrato ou convênio quando houver insuficiência de serviços públicos."]'::jsonb, 0, 'CF, art. 199, §1º e Lei 8.080/90: participação complementar, mediante contrato de direito público ou convênio, com preferência às filantrópicas e sem fins lucrativos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-006', 'sus', null, 'De acordo com o Decreto nº 7.508/2011, são Portas de Entrada às ações e aos serviços de saúde nas Redes de Atenção à Saúde os serviços:', '["de atenção primária; de atenção de urgência e emergência; de atenção psicossocial; e especiais de acesso aberto.","exclusivamente dos hospitais universitários.","de ambulatórios de especialidades, mediante encaminhamento particular.","de consultórios privados conveniados.","de laboratórios de análises clínicas e de imagem."]'::jsonb, 0, 'Art. 9º do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-007', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o acordo de colaboração firmado entre entes federativos para organizar e integrar as ações e serviços de saúde na rede regionalizada e hierarquizada denomina-se:', '["Contrato Organizativo da Ação Pública da Saúde (COAP).","Relação Nacional de Ações e Serviços de Saúde (RENASES).","Mapa da Saúde.","Comissão Intergestores Tripartite (CIT).","Protocolo Clínico e Diretriz Terapêutica (PCDT)."]'::jsonb, 0, 'COAP: define responsabilidades, indicadores, metas, recursos e critérios de avaliação. RENASES é a relação de ações e serviços; Mapa da Saúde é a descrição geográfica dos recursos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-008', 'sus', null, 'Segundo a Lei nº 8.080/1990, entende-se por vigilância epidemiológica:', '["um conjunto de ações que proporcionam o conhecimento, a detecção ou prevenção de qualquer mudança nos fatores determinantes e condicionantes de saúde individual ou coletiva, para recomendar e adotar medidas de prevenção e controle das doenças ou agravos.","um conjunto de ações capaz de eliminar, diminuir ou prevenir riscos à saúde decorrentes do meio ambiente, da produção e circulação de bens e da prestação de serviços.","um conjunto de atividades destinadas à promoção e proteção da saúde dos trabalhadores.","a política de assistência farmacêutica do SUS.","a fiscalização exclusiva de estabelecimentos comerciais de alimentos."]'::jsonb, 0, 'Art. 6º, §2º. A segunda alternativa é a definição de vigilância sanitária (§1º) e a terceira, de saúde do trabalhador (§3º).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-009', 'sus', null, 'A Lei nº 8.080/1990 (incluído pela Lei nº 11.108/2005) garante à parturiente, nos serviços do SUS, próprios ou conveniados, a presença de:', '["um acompanhante de sua indicação durante todo o período de trabalho de parto, parto e pós-parto imediato.","um acompanhante apenas no pós-parto.","acompanhante somente se for o pai da criança.","até dois acompanhantes, mediante pagamento de taxa.","acompanhante apenas em hospitais privados."]'::jsonb, 0, 'Art. 19-J da Lei 8.080/90: 1 acompanhante indicado pela parturiente, no trabalho de parto, parto e pós-parto imediato.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-010', 'sus', null, 'Para receberem os recursos do Fundo Nacional de Saúde de forma regular e automática, os Municípios deverão contar com os itens abaixo, EXCETO:', '["consórcio intermunicipal de saúde obrigatório.","Fundo de Saúde.","Conselho de Saúde com composição paritária.","plano de saúde.","relatórios de gestão."]'::jsonb, 0, 'Art. 4º da Lei 8.142/90: Fundo, Conselho paritário, plano de saúde, relatórios de gestão, contrapartida de recursos no orçamento e comissão de elaboração do PCCS. Consórcio não é exigência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-011', 'sus', null, 'Segundo a Lei nº 8.080/1990, o dever do Estado de garantir a saúde:', '["não exclui o das pessoas, da família, das empresas e da sociedade.","exclui a responsabilidade da família.","é transferido às empresas privadas em caso de insuficiência.","limita-se ao atendimento hospitalar.","aplica-se apenas aos contribuintes da previdência."]'::jsonb, 0, 'Art. 2º, §2º, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-012', 'sus', null, 'A Lei nº 8.080/1990 cita como determinantes e condicionantes da saúde, entre outros, os seguintes, EXCETO:', '["a religião.","a alimentação.","a moradia.","o saneamento básico.","o trabalho e a renda."]'::jsonb, 0, 'Art. 3º: alimentação, moradia, saneamento, meio ambiente, trabalho, renda, educação, atividade física, transporte, lazer e acesso a bens e serviços essenciais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-013', 'sus', null, 'Segundo a Lei nº 8.080/1990, o Sistema Único de Saúde é constituído pelo conjunto de ações e serviços de saúde prestados:', '["por órgãos e instituições públicas federais, estaduais e municipais, da administração direta e indireta e das fundações mantidas pelo Poder Público.","exclusivamente pelos hospitais federais.","apenas pelas secretarias municipais de saúde.","por qualquer prestador privado, independentemente de contrato.","somente pelas operadoras de planos de saúde."]'::jsonb, 0, 'Art. 4º. A iniciativa privada participa apenas em caráter complementar (§2º).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-014', 'sus', null, 'NÃO é objetivo do SUS, segundo o art. 5º da Lei nº 8.080/1990:', '["financiar planos privados de saúde para a população.","identificar e divulgar os fatores condicionantes e determinantes da saúde.","formular política de saúde destinada a promover a redução de riscos de doenças.","prestar assistência por intermédio de ações de promoção, proteção e recuperação da saúde.","realizar ações assistenciais integradas com atividades preventivas."]'::jsonb, 0, 'São três os objetivos do art. 5º: identificar/divulgar condicionantes; formular política de saúde; prestar assistência integrada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-015', 'sus', null, 'Está incluída no campo de atuação do SUS, conforme o art. 6º da Lei nº 8.080/1990:', '["a ordenação da formação de recursos humanos na área de saúde.","a fiscalização do sistema financeiro nacional.","a regulação do comércio exterior de bens de consumo.","a gestão da previdência social.","a fiscalização de concursos públicos."]'::jsonb, 0, 'O art. 6º inclui ainda vigilâncias, assistência farmacêutica, saneamento (participação), vigilância nutricional e fiscalização de produtos, entre outros.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-016', 'sus', null, 'Segundo a Lei nº 8.080/1990, a integralidade de assistência é entendida como:', '["conjunto articulado e contínuo das ações e serviços preventivos e curativos, individuais e coletivos, exigidos para cada caso em todos os níveis de complexidade do sistema.","acesso aos serviços de saúde apenas na atenção básica.","atendimento igual para todos, sem considerar necessidades.","gratuidade de todos os serviços privados.","atendimento exclusivamente hospitalar."]'::jsonb, 0, 'Art. 7º, II, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-017', 'sus', null, 'Entre os princípios do SUS previstos no art. 7º da Lei nº 8.080/1990, está a:', '["preservação da autonomia das pessoas na defesa de sua integridade física e moral.","centralização da gestão no Ministério da Saúde.","prioridade de atendimento aos contribuintes.","cobrança de taxas de manutenção dos serviços.","restrição da informação ao paciente sobre sua saúde."]'::jsonb, 0, 'Art. 7º, III. Também é princípio o direito à informação, às pessoas assistidas, sobre sua saúde (V).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-018', 'sus', null, 'A organização dos serviços públicos de modo a evitar duplicidade de meios para fins idênticos é, segundo a Lei nº 8.080/1990:', '["um princípio do SUS.","uma atribuição exclusiva da iniciativa privada.","uma vedação aos municípios.","um requisito para habilitação de planos de saúde.","uma competência exclusiva do Conselho Nacional de Saúde."]'::jsonb, 0, 'Art. 7º, XIII.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-019', 'sus', null, 'Segundo a Lei nº 8.080/1990, as ações e serviços de saúde executados pelo SUS serão organizados:', '["de forma regionalizada e hierarquizada em níveis de complexidade crescente.","de forma centralizada na União.","sem qualquer hierarquia entre níveis de atenção.","exclusivamente por meio de hospitais de alta complexidade.","de acordo com a capacidade de pagamento do usuário."]'::jsonb, 0, 'Art. 8º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-020', 'sus', null, 'De acordo com a Lei nº 8.080/1990, no âmbito dos Municípios, a direção do SUS é exercida:', '["pela respectiva Secretaria de Saúde ou órgão equivalente.","pelo Ministério da Saúde.","pela Secretaria Estadual de Saúde.","pelo Conselho Municipal de Saúde.","pela Câmara de Vereadores."]'::jsonb, 0, 'Art. 9º: União – Ministério da Saúde; Estados/DF e Municípios – Secretaria de Saúde ou órgão equivalente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-021', 'sus', null, 'Segundo a Lei nº 8.080/1990, para desenvolver em conjunto as ações e os serviços de saúde que lhes correspondam, os Municípios poderão constituir:', '["consórcios.","autarquias federais.","operadoras de planos de saúde.","conselhos tutelares.","agências reguladoras."]'::jsonb, 0, 'Art. 10. Aplica-se aos consórcios o princípio da direção única.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-022', 'sus', null, 'Segundo a Lei nº 8.080/1990, as comissões intersetoriais de âmbito nacional são:', '["subordinadas ao Conselho Nacional de Saúde.","subordinadas à Presidência da República.","vinculadas às Câmaras Municipais.","órgãos do Poder Judiciário.","independentes de qualquer instância do SUS."]'::jsonb, 0, 'Art. 12. Têm a finalidade de articular políticas e programas de interesse para a saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-023', 'sus', null, 'As Comissões Intergestores Bipartite e Tripartite são reconhecidas pela Lei nº 8.080/1990 como:', '["foros de negociação e pactuação entre gestores quanto aos aspectos operacionais do SUS.","órgãos de controle social com participação paritária de usuários.","instâncias de julgamento de processos éticos.","órgãos executores de assistência hospitalar.","conselhos de classe profissional."]'::jsonb, 0, 'Art. 14-A (incluído pela Lei 12.466/2011).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-024', 'sus', null, 'Compete à direção municipal do SUS, segundo o art. 18 da Lei nº 8.080/1990:', '["planejar, organizar, controlar e avaliar as ações e os serviços de saúde e gerir e executar os serviços públicos de saúde.","definir e coordenar os sistemas de redes integradas de alta complexidade em todo o país.","elaborar normas para regular as relações entre o SUS e os serviços privados em âmbito nacional.","formular a política nacional de sangue e hemoderivados.","controlar portos, aeroportos e fronteiras."]'::jsonb, 0, 'As demais alternativas são competências da direção nacional (art. 16).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-025', 'sus', null, 'Compete à direção nacional do SUS, segundo a Lei nº 8.080/1990:', '["definir e coordenar os sistemas de redes integradas de assistência de alta complexidade.","executar diretamente os serviços de atenção básica em cada bairro.","gerir os laboratórios públicos municipais.","executar a vigilância sanitária de padarias e restaurantes locais.","contratar agentes comunitários de saúde em cada município."]'::jsonb, 0, 'Art. 16. A execução local é atribuição predominantemente municipal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-026', 'sus', null, 'O Subsistema de Atenção à Saúde Indígena, previsto na Lei nº 8.080/1990, é financiado:', '["pela União, com recursos próprios, podendo Estados, Municípios e outras instituições atuar complementarmente.","exclusivamente pelos municípios onde estão as aldeias.","pelas próprias comunidades indígenas.","por organismos internacionais, obrigatoriamente.","pelos planos de saúde privados."]'::jsonb, 0, 'Art. 19-C (Lei 9.836/1999).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-027', 'sus', null, 'Segundo a Lei nº 8.080/1990, o atendimento e a internação domiciliares só poderão ser realizados:', '["por indicação médica, com expressa concordância do paciente e de sua família.","por solicitação do Conselho de Saúde.","quando não houver leito hospitalar, independentemente da vontade do paciente.","por determinação judicial.","apenas para pacientes com plano de saúde."]'::jsonb, 0, 'Art. 19-I, §3º (Lei 10.424/2002).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-028', 'sus', null, 'Segundo a Lei nº 8.080/1990 (redação da Lei nº 12.401/2011), a assistência terapêutica integral inclui a dispensação de medicamentos cuja prescrição esteja em conformidade com:', '["as diretrizes terapêuticas definidas em protocolo clínico para a doença ou agravo.","a preferência do usuário.","a indicação da indústria farmacêutica.","qualquer prescrição, inclusive de medicamentos sem registro.","a lista de medicamentos importados."]'::jsonb, 0, 'Art. 19-M. Na falta de protocolo, observam-se as relações de medicamentos (RENAME e listas complementares).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-029', 'sus', null, 'Segundo a Lei nº 8.080/1990, são vedados, em todas as esferas de gestão do SUS:', '["o pagamento, o ressarcimento ou o reembolso de medicamento experimental ou sem registro na ANVISA.","a dispensação de medicamentos da RENAME.","a incorporação de novas tecnologias.","a assistência farmacêutica.","o uso de protocolos clínicos."]'::jsonb, 0, 'Art. 19-T (Lei 12.401/2011), ressalvadas exceções previstas em lei.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-030', 'sus', null, 'A incorporação, exclusão ou alteração de medicamentos e tecnologias pelo SUS é atribuição do Ministério da Saúde, assessorado pela:', '["Comissão Nacional de Incorporação de Tecnologias no SUS (CONITEC).","Agência Nacional de Saúde Suplementar (ANS).","Comissão Intergestores Bipartite.","Conselho Federal de Medicina.","Câmara dos Deputados."]'::jsonb, 0, 'Art. 19-Q da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-031', 'sus', null, 'Segundo a Lei nº 8.080/1990, os recursos financeiros do SUS serão depositados em conta especial, em cada esfera de atuação, e movimentados sob fiscalização:', '["dos respectivos Conselhos de Saúde.","exclusivamente do Ministério Público.","das operadoras privadas.","do Banco Central.","dos sindicatos de trabalhadores da saúde."]'::jsonb, 0, 'Art. 33.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-032', 'sus', null, 'O processo de planejamento e orçamento do SUS, segundo a Lei nº 8.080/1990, será:', '["ascendente, do nível local até o federal, ouvidos seus órgãos deliberativos.","descendente, do nível federal ao local.","definido exclusivamente pelo Ministério da Saúde.","elaborado apenas pelos estados.","anual e sem participação dos conselhos."]'::jsonb, 0, 'Art. 36.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-033', 'sus', null, 'Segundo a Lei nº 8.080/1990, a gratuidade das ações e serviços de saúde fica preservada:', '["nos serviços públicos contratados e nos privados contratados ou conveniados.","apenas nos hospitais universitários.","somente para pessoas de baixa renda.","apenas na atenção básica.","somente em situações de emergência."]'::jsonb, 0, 'Art. 43.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-034', 'sus', null, 'Segundo a Lei nº 8.142/1990, o Conselho de Saúde:', '["tem caráter permanente e deliberativo e atua na formulação de estratégias e no controle da execução da política de saúde, inclusive nos aspectos econômicos e financeiros.","reúne-se a cada quatro anos.","tem caráter apenas consultivo.","é formado exclusivamente por usuários.","tem suas decisões homologadas pelo Ministério Público."]'::jsonb, 0, 'Art. 1º, §2º. As decisões são homologadas pelo chefe do poder legalmente constituído em cada esfera de governo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-035', 'sus', null, 'Segundo a Lei nº 8.142/1990, terão representação no Conselho Nacional de Saúde:', '["o Conselho Nacional de Secretários de Saúde (CONASS) e o Conselho Nacional de Secretarias Municipais de Saúde (CONASEMS).","a Ordem dos Advogados do Brasil e o Ministério Público.","apenas os conselhos de classe profissional.","o Senado Federal e a Câmara dos Deputados.","as operadoras de planos de saúde, obrigatoriamente."]'::jsonb, 0, 'Art. 1º, §3º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-036', 'sus', null, 'Segundo a Lei nº 8.142/1990, dos recursos destinados à cobertura das ações e serviços a serem implementados por Municípios, Estados e DF, serão repassados aos Municípios, no mínimo:', '["70%.","30%.","50%.","15%.","100%."]'::jsonb, 0, 'Art. 3º, §2º: pelo menos 70% aos Municípios, afetando-se o restante aos Estados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-037', 'sus', null, 'Segundo a Lei nº 8.142/1990, quando o Município não atender aos requisitos para recebimento de recursos (Fundo, Conselho, plano etc.):', '["os recursos serão administrados pelo Estado ou pela União.","os recursos serão perdidos definitivamente.","o prefeito será afastado.","o Conselho Municipal administrará os recursos.","os recursos serão repassados a instituições privadas."]'::jsonb, 0, 'Art. 4º, parágrafo único.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-038', 'sus', null, 'Segundo o art. 197 da Constituição Federal, as ações e serviços de saúde:', '["são de relevância pública, cabendo ao Poder Público dispor sobre sua regulamentação, fiscalização e controle.","são de interesse exclusivamente privado.","só podem ser executados diretamente pelo Estado.","são regulados apenas pelos municípios.","não podem ser executados por pessoa física."]'::jsonb, 0, 'A execução pode ser direta ou por terceiros, inclusive pessoa física ou jurídica de direito privado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-039', 'sus', null, 'De acordo com a Constituição Federal, é vedada:', '["a destinação de recursos públicos para auxílios ou subvenções às instituições privadas com fins lucrativos.","a participação de entidades filantrópicas no SUS.","a contratação de serviços privados de forma complementar.","a participação da comunidade no SUS.","a existência de serviços privados de saúde."]'::jsonb, 0, 'Art. 199, §2º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-040', 'sus', null, 'Segundo a Constituição Federal, quanto à remoção de órgãos, tecidos e substâncias humanas para fins de transplante, pesquisa e tratamento:', '["é vedado todo tipo de comercialização.","é permitida a venda mediante autorização judicial.","é permitida a comercialização entre parentes.","a comercialização é livre para fins de pesquisa.","a comercialização depende de autorização do Conselho de Saúde."]'::jsonb, 0, 'Art. 199, §4º. O mesmo vale para coleta, processamento e transfusão de sangue e derivados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-041', 'sus', null, 'Compete ao SUS, nos termos do art. 200 da Constituição Federal, EXCETO:', '["julgar os crimes contra a saúde pública.","executar as ações de vigilância sanitária e epidemiológica e de saúde do trabalhador.","ordenar a formação de recursos humanos na área de saúde.","participar da formulação da política e da execução das ações de saneamento básico.","colaborar na proteção do meio ambiente, nele compreendido o do trabalho."]'::jsonb, 0, 'Julgar crimes é função do Poder Judiciário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-042', 'sus', null, 'Segundo a Constituição Federal, o SUS será financiado:', '["com recursos do orçamento da seguridade social, da União, dos Estados, do DF e dos Municípios, além de outras fontes.","exclusivamente com recursos da União.","exclusivamente com contribuições dos usuários.","apenas com recursos municipais.","por meio de taxas cobradas nos atendimentos."]'::jsonb, 0, 'Art. 198, §1º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-043', 'sus', null, 'Segundo a Lei Complementar nº 141/2012, os Municípios devem aplicar anualmente em ações e serviços públicos de saúde, no mínimo:', '["15% da arrecadação de impostos e transferências constitucionais.","12% da arrecadação de impostos.","5% do orçamento total.","25% da arrecadação de impostos.","30% da receita corrente líquida."]'::jsonb, 0, 'Municípios: 15%; Estados: 12%. A União segue regra própria definida na Constituição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-044', 'sus', null, 'Segundo a Lei Complementar nº 141/2012, NÃO constitui despesa com ações e serviços públicos de saúde, para fins de apuração do mínimo constitucional:', '["a merenda escolar.","a vigilância em saúde.","a atenção integral e universal à saúde em todos os níveis de complexidade.","a capacitação de pessoal de saúde do SUS.","a produção e aquisição de medicamentos e insumos para o SUS."]'::jsonb, 0, 'O art. 4º exclui, entre outros, merenda escolar, aposentadorias e pensões, limpeza urbana e assistência social.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-045', 'sus', null, 'Segundo o Decreto nº 7.508/2011, Região de Saúde é:', '["o espaço geográfico contínuo constituído por agrupamentos de Municípios limítrofes, delimitado a partir de identidades culturais, econômicas e sociais e de redes de comunicação e infraestrutura de transportes compartilhados.","o território de abrangência de uma equipe de saúde da família.","a área de atuação de um único hospital.","o conjunto de estados de uma macrorregião do IBGE.","o bairro onde reside o usuário."]'::jsonb, 0, 'Art. 2º, I, do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-046', 'sus', null, 'Segundo o Decreto nº 7.508/2011, para ser instituída, a Região de Saúde deve conter, no mínimo, ações e serviços de, EXCETO:', '["assistência odontológica privada.","atenção primária.","urgência e emergência.","atenção psicossocial.","vigilância em saúde."]'::jsonb, 0, 'Art. 5º: atenção primária, urgência e emergência, atenção psicossocial, atenção ambulatorial especializada e hospitalar, e vigilância em saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-047', 'sus', null, 'Segundo o Decreto nº 7.508/2011, a descrição geográfica da distribuição de recursos humanos e de ações e serviços de saúde ofertados pelo SUS e pela iniciativa privada denomina-se:', '["Mapa da Saúde.","Rede de Atenção à Saúde.","Região de Saúde.","Protocolo Clínico.","Contrato Organizativo da Ação Pública."]'::jsonb, 0, 'Art. 2º, V. É usado na identificação das necessidades de saúde e no planejamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-048', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o acesso universal e igualitário à assistência farmacêutica pressupõe, cumulativamente, EXCETO:', '["possuir plano de saúde privado.","estar o usuário assistido por ações e serviços de saúde do SUS.","ter o medicamento sido prescrito por profissional de saúde no exercício regular de suas funções no SUS.","estar a prescrição em conformidade com a RENAME e os PCDT.","ter a dispensação ocorrido em unidades indicadas pela direção do SUS."]'::jsonb, 0, 'Art. 28 do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-049', 'sus', null, 'Segundo o Decreto nº 7.508/2011, a Comissão Intergestores Regional (CIR) atua no âmbito:', '["regional, vinculada à Secretaria Estadual de Saúde.","nacional, vinculada ao Ministério da Saúde.","estadual, vinculada à Assembleia Legislativa.","municipal, vinculada à Câmara de Vereadores.","internacional, vinculada à OMS."]'::jsonb, 0, 'CIT: União; CIB: Estado; CIR: Região de Saúde (vinculada à SES para efeitos administrativos e operacionais).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-050', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o acesso universal, igualitário e ordenado às ações e serviços de saúde se inicia pelas Portas de Entrada do SUS e se completa na rede regionalizada e hierarquizada. Esse acesso será ordenado pela:', '["atenção primária.","atenção hospitalar.","regulação judicial.","iniciativa privada.","atenção de alta complexidade."]'::jsonb, 0, 'Art. 11: o acesso será ordenado pela atenção primária, de acordo com a avaliação da gravidade do risco individual e coletivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-051', 'sus', null, 'Segundo a Política Nacional de Atenção Básica (Portaria nº 2.436/2017), são princípios do SUS e da Rede de Atenção à Saúde a serem operacionalizados na Atenção Básica:', '["universalidade, equidade e integralidade.","centralização, hierarquização e privatização.","territorialização, adscrição e resolutividade.","regionalização, cogestão e ambiência.","longitudinalidade, coordenação e ordenação."]'::jsonb, 0, 'Os princípios são universalidade, equidade e integralidade. Territorialização, longitudinalidade etc. são diretrizes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-052', 'sus', null, 'Segundo a PNAB (Portaria nº 2.436/2017), a composição mínima da equipe de Saúde da Família (eSF) é:', '["médico, enfermeiro, auxiliar e/ou técnico de enfermagem e agente comunitário de saúde.","médico, dentista e farmacêutico.","enfermeiro e agente de combate às endemias, apenas.","médico, psicólogo e assistente social.","médico e técnico de enfermagem, apenas."]'::jsonb, 0, 'Podem ser acrescentados o agente de combate às endemias e os profissionais de saúde bucal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-053', 'sus', null, 'Segundo a PNAB (Portaria nº 2.436/2017), a população adscrita por equipe de Atenção Básica e de Saúde da Família recomendada é de:', '["2.000 a 3.500 pessoas.","500 a 1.000 pessoas.","5.000 a 8.000 pessoas.","10.000 pessoas.","até 750 famílias por agente comunitário."]'::jsonb, 0, 'PNAB 2017: 2.000 a 3.500 pessoas, podendo variar conforme vulnerabilidade e critérios locais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-054', 'sus', null, 'Na PNAB, a diretriz que se refere à continuidade da relação de cuidado, com construção de vínculo e responsabilização entre profissionais e usuários ao longo do tempo, é a:', '["longitudinalidade do cuidado.","territorialização.","resolutividade.","regionalização.","população adscrita."]'::jsonb, 0, 'Longitudinalidade = acompanhamento ao longo do tempo, de modo permanente e consistente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-055', 'sus', null, 'Segundo a PNAB (Portaria nº 2.436/2017), a carga horária dos profissionais da equipe de Saúde da Família é de:', '["40 horas semanais.","20 horas semanais.","30 horas semanais.","12 horas por plantão.","60 horas semanais."]'::jsonb, 0, 'Na eSF todos os profissionais cumprem 40 h semanais. Equipes de Atenção Básica (eAB) podem ter carga mínima de 10 h por categoria.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-056', 'sus', null, 'Segundo a Carta dos Direitos dos Usuários da Saúde (Portaria nº 1.820/2009), é direito da pessoa:', '["ser identificada pelo nome e sobrenome civil, nunca por número, código ou nome da doença.","escolher livremente o profissional em qualquer serviço, sem regulação.","receber medicamentos sem prescrição.","ter acesso ao prontuário de outros pacientes.","ser atendida sem qualquer ordem de prioridade."]'::jsonb, 0, 'A Carta também garante o uso do nome social e o acesso ao próprio prontuário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-057', 'sus', null, 'São diretrizes da Política Nacional de Humanização (HumanizaSUS):', '["acolhimento, clínica ampliada, cogestão, ambiência, valorização do trabalhador e defesa dos direitos dos usuários.","centralização das decisões e hierarquização rígida das equipes.","redução de custos por meio da privatização.","triagem por ordem de chegada e atendimento exclusivamente médico.","padronização dos atendimentos sem considerar singularidades."]'::jsonb, 0, 'A PNH (2003) busca transformar os modos de gerir e de cuidar, com protagonismo de usuários e trabalhadores.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-058', 'sus', null, 'O Pacto pela Saúde (2006) é composto por três dimensões:', '["Pacto pela Vida, Pacto em Defesa do SUS e Pacto de Gestão.","Pacto pela Vida, Pacto pela Morte Digna e Pacto Federativo.","Pacto de Financiamento, Pacto Privado e Pacto Social.","Pacto da Atenção Básica, Pacto Hospitalar e Pacto Farmacêutico.","Pacto Municipal, Pacto Estadual e Pacto Internacional."]'::jsonb, 0, 'Pacto pela Vida (prioridades sanitárias), em Defesa do SUS (repolitização) e de Gestão (responsabilidades dos entes).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-059', 'sus', null, 'Segundo a Lei nº 8.080/1990, a igualdade da assistência à saúde deve ocorrer:', '["sem preconceitos ou privilégios de qualquer espécie.","com prioridade aos contribuintes da previdência.","conforme a renda do usuário.","apenas entre usuários do mesmo município.","mediante pagamento de taxa de igualdade."]'::jsonb, 0, 'Art. 7º, IV, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-060', 'sus', null, 'Segundo a Lei nº 8.142/1990, a Conferência de Saúde será convocada:', '["pelo Poder Executivo ou, extraordinariamente, por esta ou pelo Conselho de Saúde.","exclusivamente pelo Ministério Público.","pelo Poder Judiciário.","apenas pelos usuários, mediante abaixo-assinado.","pelo Congresso Nacional, a cada dez anos."]'::jsonb, 0, 'Art. 1º, §1º. Reúne-se a cada quatro anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-061', 'sus', null, 'Segundo a Constituição Federal de 1988, a seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade destinadas a assegurar os direitos relativos à:', '["saúde, à previdência e à assistência social.","saúde, à educação e à segurança pública.","previdência, ao trabalho e à moradia.","saúde, à alimentação e ao lazer.","assistência social, à cultura e ao transporte."]'::jsonb, 0, 'Art. 194 da CF/88. A saúde integra o capítulo da Seguridade Social, no Título VIII (Da Ordem Social).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-062', 'sus', null, 'Acerca da saúde na Constituição Federal de 1988, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-063', 'sus', null, 'De acordo com o art. 200 da Constituição Federal, compete ao SUS, além de outras atribuições:', '["incrementar, em sua área de atuação, o desenvolvimento científico e tecnológico e a inovação.","regular as tarifas de energia elétrica dos hospitais privados.","julgar as infrações éticas dos profissionais de saúde.","definir o currículo das escolas de ensino fundamental.","administrar os fundos de previdência dos servidores da saúde."]'::jsonb, 0, 'Art. 200, V (redação da EC 85/2015). Também cabe ao SUS ordenar a formação de recursos humanos, executar vigilâncias e participar do saneamento básico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-064', 'sus', null, 'A Lei nº 8.080/1990 estabelece princípios e diretrizes para as ações e serviços públicos de saúde e para os serviços privados contratados ou conveniados que integram o SUS. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-065', 'sus', null, 'A Lei nº 8.080/1990 estabelece os princípios e diretrizes que orientam as ações e os serviços públicos de saúde. Com base nessas disposições, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-066', 'sus', null, 'A Lei nº 8.080/1990 inclui entre os princípios do SUS a integração, em nível executivo, das ações de saúde com as de:', '["meio ambiente e saneamento básico.","segurança pública e defesa civil.","educação e cultura.","previdência e assistência social.","habitação e transporte urbano."]'::jsonb, 0, 'Art. 7º, X: integração em nível executivo das ações de saúde, meio ambiente e saneamento básico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-067', 'sus', null, 'A Lei nº 8.080/1990 prevê a criação de comissões intersetoriais de âmbito nacional, subordinadas ao Conselho Nacional de Saúde, destinadas a articular políticas e programas de interesse para a saúde. Sobre as atividades que essas comissões abrangerão, em especial, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-068', 'sus', null, 'Segundo a Lei nº 8.080/1990, deverão ser criadas comissões permanentes de integração entre:', '["os serviços de saúde e as instituições de ensino profissional e superior.","os hospitais privados e as operadoras de planos de saúde.","o Ministério da Saúde e os organismos internacionais.","as secretarias de saúde e o Poder Judiciário.","os conselhos de classe e as câmaras municipais."]'::jsonb, 0, 'Art. 14. Essas comissões propõem prioridades, métodos e estratégias para a formação e a educação continuada dos recursos humanos do SUS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-069', 'sus', null, 'A Lei nº 8.080/1990 reconhece o Conselho Nacional de Secretários de Saúde (CONASS) e o Conselho Nacional de Secretarias Municipais de Saúde (CONASEMS) como:', '["entidades representativas dos entes estaduais e municipais para tratar de matérias referentes à saúde.","órgãos executores da assistência hospitalar de alta complexidade.","instâncias de controle social com representação paritária de usuários.","órgãos de fiscalização do exercício profissional.","conselhos subordinados ao Ministério da Previdência."]'::jsonb, 0, 'Art. 14-B. Os COSEMS são reconhecidos como representantes dos municípios no âmbito estadual.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-070', 'sus', null, 'Considerando a estrutura de gestão do SUS, a Comissão Intergestores Tripartite (CIT) é:', '["a instância de pactuação no âmbito da União, composta paritariamente por representantes do Ministério da Saúde, do CONASS e do CONASEMS.","a instância de pactuação no âmbito municipal, composta pela Secretaria Municipal de Saúde e pela Câmara Municipal.","o órgão de controle social no nível estadual, composto por usuários e trabalhadores.","a instância de pactuação estadual, composta apenas pelo Secretário Estadual de Saúde.","o comitê gestor municipal formado pelos diretores dos hospitais privados contratados."]'::jsonb, 0, 'CIT: União (MS + CONASS + CONASEMS); CIB: Estado (SES + COSEMS); CIR: Região de Saúde. São instâncias de pactuação entre gestores, não de controle social.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-071', 'sus', null, 'Segundo a Lei nº 8.080/1990, para atender a necessidades coletivas, urgentes e transitórias, decorrentes de situações de perigo iminente, de calamidade pública ou de irrupção de epidemias, a autoridade competente da esfera administrativa correspondente poderá:', '["requisitar bens e serviços, tanto de pessoas naturais como de jurídicas, sendo-lhes assegurada justa indenização.","confiscar bens privados sem qualquer indenização.","suspender o funcionamento do Conselho de Saúde.","dispensar a participação da comunidade nas decisões.","transferir a gestão do SUS para a iniciativa privada."]'::jsonb, 0, 'Art. 15, XIII, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-072', 'sus', null, 'A Lei nº 8.080/1990 define competências para a direção municipal do SUS. Registre V para as competências municipais e F para as que não são atribuídas ao município.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-073', 'sus', null, 'De acordo com a Lei nº 8.080/1990, compete à direção estadual do SUS:', '["promover a descentralização para os municípios dos serviços e das ações de saúde e prestar-lhes apoio técnico e financeiro.","executar diretamente todas as ações de atenção básica dos municípios.","definir as normas nacionais de vigilância sanitária de portos e aeroportos.","formular a política nacional de sangue e hemoderivados.","celebrar contratos com organismos internacionais em nome da União."]'::jsonb, 0, 'Art. 17, I e III. As competências nacionais e as municipais estão nos arts. 16 e 18.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-074', 'sus', null, 'Segundo a Lei nº 8.080/1990, quando as suas disponibilidades forem insuficientes para garantir a cobertura assistencial à população de uma determinada área, o SUS poderá recorrer aos serviços ofertados pela iniciativa privada, sendo essa participação complementar formalizada mediante:', '["contrato ou convênio, observadas as normas de direito público.","acordo verbal entre o gestor e o prestador.","doação voluntária dos serviços pelo prestador.","decreto do Poder Legislativo municipal.","simples cadastro do estabelecimento no conselho de classe."]'::jsonb, 0, 'Arts. 24 e 25 da Lei 8.080/90. Têm preferência as entidades filantrópicas e as sem fins lucrativos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-075', 'sus', null, 'Segundo a Lei nº 8.080/1990, os critérios e valores para a remuneração de serviços e os parâmetros de cobertura assistencial são estabelecidos pela direção nacional do SUS e aprovados:', '["no Conselho Nacional de Saúde.","pela Agência Nacional de Saúde Suplementar.","pelas câmaras municipais.","pelos conselhos de classe profissional.","pelo Tribunal de Contas da União."]'::jsonb, 0, 'Art. 26 da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-076', 'sus', null, 'Conforme a Lei nº 8.080/1990, os cargos e funções de chefia, direção e assessoramento, no âmbito do SUS, só poderão ser exercidos:', '["em regime de tempo integral.","por profissionais com mais de dez anos de serviço.","por servidores federais.","mediante indicação do Conselho de Saúde.","por médicos, exclusivamente."]'::jsonb, 0, 'Art. 28 da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-077', 'sus', null, 'De acordo com a Lei nº 8.080/1990, os serviços públicos que integram o SUS constituem:', '["campo de prática para ensino e pesquisa, mediante normas específicas elaboradas conjuntamente com o sistema educacional.","espaços exclusivos de assistência, vedada a atividade de ensino.","unidades subordinadas às universidades privadas.","locais de estágio apenas para estudantes de medicina.","serviços de caráter militar."]'::jsonb, 0, 'Art. 27, parágrafo único.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-078', 'sus', null, 'Os serviços de saúde dos hospitais universitários e de ensino, segundo a Lei nº 8.080/1990:', '["integram-se ao SUS mediante convênio, preservada a sua autonomia administrativa em relação ao patrimônio, aos recursos humanos e financeiros, ao ensino, à pesquisa e à extensão.","não podem integrar o SUS.","integram o SUS automaticamente, perdendo sua autonomia administrativa.","integram-se ao SUS apenas para atendimentos de urgência.","subordinam-se exclusivamente ao Ministério da Educação, sem relação com o SUS."]'::jsonb, 0, 'Art. 45 da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-079', 'sus', null, 'Considerando as disposições da Lei nº 8.080/1990 sobre a assistência terapêutica e a incorporação de tecnologias, incluídas pela Lei nº 12.401/2011, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-080', 'sus', null, 'A Lei nº 8.080/1990 define o campo de atuação da saúde do trabalhador. Sobre as ações nela previstas, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-081', 'sus', null, 'A Lei nº 8.142/1990 dispõe sobre a participação da comunidade na gestão do SUS e sobre as transferências intergovernamentais de recursos. São instâncias colegiadas do SUS, em cada esfera de governo, previstas nessa lei:', '["a Conferência de Saúde e o Conselho de Saúde.","a Comissão Intergestores Bipartite e a Comissão Intergestores Tripartite.","a Ouvidoria e a Auditoria do SUS.","o Fundo de Saúde e o Plano de Saúde.","a Agência Nacional de Vigilância Sanitária e a Agência Nacional de Saúde Suplementar."]'::jsonb, 0, 'Art. 1º da Lei 8.142/90. As Comissões Intergestores são instâncias de pactuação entre gestores, previstas na Lei 8.080/90 e no Decreto 7.508/11.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-082', 'sus', null, 'Segundo a Resolução CNS nº 453/2012, as vagas nos Conselhos de Saúde devem ser distribuídas da seguinte forma:', '["50% de entidades e movimentos representativos de usuários, 25% de trabalhadores de saúde e 25% de representação de governo e prestadores de serviços.","25% de usuários, 25% de trabalhadores e 50% de gestores.","33% para cada segmento: usuários, trabalhadores e gestores.","50% de gestores e 50% de trabalhadores.","100% de usuários, por se tratar de controle social."]'::jsonb, 0, 'A paridade prevista na Lei 8.142/90 é detalhada na Resolução 453/2012: usuários = 50%; trabalhadores = 25%; governo e prestadores = 25%.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-083', 'sus', null, 'Com base na Lei nº 8.142/1990, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-084', 'sus', null, 'Segundo a Lei nº 8.142/1990, os recursos do Fundo Nacional de Saúde serão alocados como, EXCETO:', '["pagamento de planos de saúde privados para servidores públicos.","despesas de custeio e de capital do Ministério da Saúde, seus órgãos e entidades.","investimentos previstos em lei orçamentária, de iniciativa do Poder Legislativo e aprovados pelo Congresso Nacional.","investimentos previstos no Plano Quinquenal do Ministério da Saúde.","cobertura das ações e serviços de saúde a serem implementados pelos Municípios, Estados e Distrito Federal."]'::jsonb, 0, 'Art. 2º da Lei 8.142/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-085', 'sus', null, 'Segundo o Decreto nº 7.508/2011, a Rede de Atenção à Saúde (RAS) é definida como:', '["o conjunto de ações e serviços de saúde articulados em níveis de complexidade crescente, com a finalidade de garantir a integralidade da assistência à saúde.","o conjunto de hospitais de alta complexidade de uma capital.","a relação de todos os medicamentos ofertados pelo SUS.","o acordo de colaboração firmado entre os entes federativos.","o espaço geográfico formado por municípios limítrofes."]'::jsonb, 0, 'Art. 2º, VI. O acordo de colaboração é o COAP; o espaço geográfico é a Região de Saúde; a relação de medicamentos é a RENAME.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-086', 'sus', null, 'O Decreto nº 7.508/2011 define "Serviços Especiais de Acesso Aberto" como:', '["serviços de saúde específicos para o atendimento da pessoa que, em razão de agravo ou de situação laboral, necessita de atendimento especial.","serviços privados que atendem sem necessidade de encaminhamento mediante pagamento.","hospitais de ensino com portas abertas 24 horas.","unidades de pronto atendimento que dispensam a classificação de risco.","farmácias populares conveniadas ao SUS."]'::jsonb, 0, 'Art. 2º, IV. São exemplos os serviços de referência em saúde do trabalhador (CEREST) e os de atenção às pessoas com HIV/aids.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-087', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o documento que estabelece critérios para o diagnóstico da doença ou do agravo, o tratamento preconizado, com os medicamentos e demais produtos apropriados, as posologias recomendadas, os mecanismos de controle clínico e o acompanhamento e a verificação dos resultados terapêuticos, é o:', '["Protocolo Clínico e Diretriz Terapêutica (PCDT).","Mapa da Saúde.","Contrato Organizativo da Ação Pública da Saúde.","Relatório Anual de Gestão.","Plano Diretor de Regionalização."]'::jsonb, 0, 'Art. 2º, VIII, do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-088', 'sus', null, 'De acordo com o Decreto nº 7.508/2011, analise as afirmativas a seguir sobre a organização do SUS.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-089', 'sus', null, 'Segundo o Decreto nº 7.508/2011, a Relação Nacional de Medicamentos Essenciais (RENAME) e a Relação Nacional de Ações e Serviços de Saúde (RENASES) terão suas atualizações consolidadas e publicadas pelo Ministério da Saúde a cada:', '["dois anos.","seis meses.","quatro anos.","cinco anos.","dez anos."]'::jsonb, 0, 'Arts. 22 e 25, parágrafo único, do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-090', 'sus', null, 'Conforme o Decreto nº 7.508/2011, os serviços de atenção hospitalar e os ambulatoriais especializados, entre outros de maior complexidade e densidade tecnológica, serão:', '["referenciados pelas Portas de Entrada.","acessados livremente, sem necessidade de encaminhamento.","ofertados exclusivamente pela iniciativa privada.","organizados sem relação com a atenção primária.","acessados somente por decisão judicial."]'::jsonb, 0, 'Art. 10. O acesso universal e igualitário se inicia nas Portas de Entrada e se completa na rede regionalizada e hierarquizada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-091', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o ente federativo assegurará ao usuário:', '["a continuidade do cuidado em saúde, em todas as suas modalidades, nos serviços, hospitais e demais ambulatórios que constituem as redes de atenção da respectiva região.","o atendimento exclusivo em serviços do seu município de residência.","a escolha livre de qualquer serviço, sem considerar a regulação.","o acesso a medicamentos não registrados na ANVISA.","atendimento prioritário em hospitais privados não conveniados."]'::jsonb, 0, 'Art. 13 do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-092', 'sus', null, 'Segundo a Lei Complementar nº 141/2012, o gestor do SUS em cada ente da Federação deve apresentar, em audiência pública na Casa Legislativa do respectivo ente, até o final dos meses de maio, setembro e fevereiro:', '["o Relatório Detalhado referente ao quadrimestre anterior.","o Plano Plurianual de Saúde.","o Relatório Anual de Gestão do exercício seguinte.","a lista de servidores contratados.","a proposta de Conferência de Saúde."]'::jsonb, 0, 'Art. 36 da LC 141/2012. O Relatório Anual de Gestão deve ser enviado ao Conselho de Saúde até 30 de março do ano seguinte.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-093', 'sus', null, 'Para fins de apuração da aplicação dos recursos mínimos em ações e serviços públicos de saúde, a Lei Complementar nº 141/2012 define o que pode ser considerado despesa com saúde. Registre V para o que é considerado despesa em saúde e F para o que não é.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-094', 'sus', null, 'Segundo a Lei Complementar nº 141/2012, os Estados devem aplicar, anualmente, em ações e serviços públicos de saúde, no mínimo:', '["12% da arrecadação dos impostos e das transferências constitucionais, deduzidas as parcelas transferidas aos Municípios.","15% da arrecadação dos impostos.","25% da receita corrente líquida.","5% do orçamento total.","o mesmo valor aplicado pela União no ano anterior."]'::jsonb, 0, 'Estados: 12%; Municípios: 15%.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-095', 'sus', null, 'Segundo a Política Nacional de Atenção Básica (PNAB/2017), a Atenção Básica é o conjunto de ações de saúde individuais, familiares e coletivas que envolvem:', '["promoção, prevenção, proteção, diagnóstico, tratamento, reabilitação, redução de danos, cuidados paliativos e vigilância em saúde.","exclusivamente consultas médicas e dispensação de medicamentos.","apenas ações de vacinação e pré-natal.","atendimentos de urgência e internações de curta duração.","procedimentos de alta complexidade realizados em ambulatórios especializados."]'::jsonb, 0, 'Conceito da PNAB (Portaria 2.436/2017), desenvolvido por meio de práticas de cuidado integrado e gestão qualificada, com equipe multiprofissional e população adscrita.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-096', 'sus', null, 'A Política Nacional de Atenção Básica (PNAB) estabelece as diretrizes essenciais para a organização da Atenção Básica. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-097', 'sus', null, 'A PNAB atribui à Atenção Básica funções na Rede de Atenção à Saúde. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-098', 'sus', null, 'De acordo com a PNAB/2017, a Unidade Básica de Saúde deve funcionar com carga horária mínima de:', '["40 horas semanais, no mínimo 5 dias da semana e nos 12 meses do ano.","20 horas semanais, 3 dias por semana.","24 horas por dia, todos os dias.","30 horas semanais, exceto nos meses de férias.","40 horas semanais, apenas nos dias úteis de 10 meses do ano."]'::jsonb, 0, 'A PNAB admite horários alternativos pactuados com a comunidade, respeitada a carga horária mínima.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-099', 'sus', null, 'Segundo a PNAB/2017, o número de agentes comunitários de saúde por equipe deve ser definido de acordo com a base populacional, os critérios demográficos, epidemiológicos e socioeconômicos, observado o limite máximo de:', '["750 pessoas por ACS.","200 pessoas por ACS.","1.500 pessoas por ACS.","3.500 pessoas por ACS.","100 famílias por ACS."]'::jsonb, 0, 'Em áreas de risco e vulnerabilidade social, recomenda-se cobertura de 100% da população.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-100', 'sus', null, 'De acordo com a PNAB/2017, são diretrizes da Atenção Básica, EXCETO uma delas. Registre V para as diretrizes previstas e F para a que não é diretriz da PNAB.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-101', 'sus', null, 'A PNAB/2017 recomenda a inclusão, nas Unidades Básicas de Saúde, do gerente de Atenção Básica, que deve ser, preferencialmente:', '["um profissional qualificado, com experiência na Atenção Básica e que não seja integrante das equipes vinculadas à UBS.","o médico mais antigo da equipe.","o agente comunitário de saúde com maior tempo de serviço.","um representante dos usuários eleito pelo Conselho Local.","obrigatoriamente o enfermeiro da equipe de Saúde da Família."]'::jsonb, 0, 'O gerente contribui para o aprimoramento e a qualificação do processo de trabalho na UBS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-102', 'sus', null, 'Considerando as atribuições do enfermeiro na Atenção Básica, segundo a PNAB/2017, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-103', 'sus', null, 'Segundo a PNAB/2017, é atribuição do técnico de enfermagem na Atenção Básica:', '["participar das atividades de atenção, realizando procedimentos regulamentados no exercício de sua profissão na UBS e, quando indicado ou necessário, no domicílio e nos demais espaços comunitários.","realizar a consulta de enfermagem e prescrever a assistência de enfermagem.","coordenar a equipe de Saúde da Família.","definir o diagnóstico médico dos usuários.","aprovar o plano municipal de saúde."]'::jsonb, 0, 'O técnico participa da atenção, de ações de educação em saúde e do gerenciamento de insumos, sob supervisão do enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-104', 'sus', null, 'Acerca das atribuições comuns a todos os membros das equipes que atuam na Atenção Básica, segundo a PNAB/2017, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-105', 'sus', null, 'A PNAB prevê a equipe de Consultório na Rua (eCR), que tem como objetivo:', '["ampliar o acesso da população em situação de rua aos serviços de saúde, ofertando atenção integral de forma itinerante.","realizar exclusivamente a remoção compulsória de pessoas em situação de rua.","substituir os CAPS no cuidado em saúde mental.","atender apenas pessoas em situação de rua com plano de saúde.","realizar internações hospitalares de longa permanência."]'::jsonb, 0, 'As eCR atuam de forma itinerante, articuladas às UBS e à rede, inclusive na atenção a pessoas que usam álcool e outras drogas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-106', 'sus', null, 'A Portaria GM/MS nº 635/2023 instituiu, no âmbito da Atenção Primária à Saúde, as:', '["equipes Multiprofissionais (eMulti), que atuam de forma integrada às equipes de Atenção Primária.","Unidades de Pronto Atendimento 24 horas.","Centrais de Regulação Médica das Urgências.","equipes de Consultório na Rua.","Comissões Intergestores Regionais."]'::jsonb, 0, 'As eMulti sucederam o NASF-AB, ampliando o apoio multiprofissional às equipes da APS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-107', 'sus', null, 'Associe os tipos de equipe da Atenção Básica às suas características.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-108', 'sus', null, 'Associe as esferas de gestão às respectivas responsabilidades pela Atenção Básica, segundo a PNAB.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-109', 'sus', null, 'A Política Nacional de Humanização (PNH) tem entre os seus princípios:', '["a transversalidade, a indissociabilidade entre atenção e gestão e o protagonismo, a corresponsabilidade e a autonomia dos sujeitos e coletivos.","a centralização das decisões e a hierarquia rígida entre profissionais.","a competição interprofissional como forma de aumentar a produtividade.","o foco exclusivo na doença e nos protocolos clínicos.","a redução de custos como finalidade principal."]'::jsonb, 0, 'Os três princípios da PNH: transversalidade; indissociabilidade entre atenção e gestão; protagonismo, corresponsabilidade e autonomia dos sujeitos e dos coletivos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-110', 'sus', null, 'Sobre as diretrizes da Política Nacional de Humanização (PNH), registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-111', 'sus', null, 'Uma Unidade de Pronto Atendimento enfrenta longos tempos de espera e queixas sobre falta de informação. A gestão decide implantar um dispositivo da PNH para garantir que todo usuário seja ouvido, tenha suas necessidades avaliadas segundo critérios de gravidade e seja encaminhado de forma responsável. Esse dispositivo é o:', '["Acolhimento com Classificação de Risco.","Projeto Terapêutico Singular.","Grupo de Trabalho de Humanização.","Colegiado Gestor.","Visita Aberta."]'::jsonb, 0, 'O ACCR organiza o atendimento pela gravidade e pelo risco, e não pela ordem de chegada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-112', 'sus', null, 'No âmbito da PNH, o dispositivo que garante ao usuário internado o direito de receber visitas de forma ampliada e de ter a presença de acompanhante, respeitando a dinâmica de cada unidade, é denominado:', '["Visita Aberta e Direito a Acompanhante.","Ambiência.","Ouvidoria.","Clínica Ampliada.","Equipe de Referência."]'::jsonb, 0, 'O dispositivo amplia o acesso da rede social do usuário ao espaço de internação, favorecendo o vínculo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-113', 'sus', null, 'Na PNH, o Grupo de Trabalho de Humanização (GTH) é um dispositivo que:', '["reúne trabalhadores, gestores e usuários para discutir e implementar melhorias nos processos de trabalho e na qualidade da atenção.","fiscaliza o cumprimento de metas de produtividade.","substitui o Conselho de Saúde no controle social.","realiza a regulação de leitos hospitalares.","audita as contas da unidade de saúde."]'::jsonb, 0, 'O GTH é um espaço coletivo de análise e intervenção sobre o cotidiano do serviço.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-114', 'sus', null, 'Na PNH, a diretriz que propõe o trabalho em equipe e o compartilhamento de saberes, ampliando o objeto de trabalho da clínica para além da doença e considerando o sujeito em seu contexto, é a:', '["Clínica Ampliada e Compartilhada.","Ambiência.","Gestão Participativa.","Valorização do Trabalhador.","Defesa dos Direitos dos Usuários."]'::jsonb, 0, 'A clínica ampliada reconhece a singularidade de cada pessoa e a complexidade do adoecimento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-115', 'sus', null, 'A Carta dos Direitos dos Usuários da Saúde (Portaria nº 1.820/2009) assegura direitos e estabelece deveres. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-116', 'sus', null, 'Segundo a Carta dos Direitos dos Usuários da Saúde, é direito da pessoa, no atendimento:', '["ser identificada pelo nome e sobrenome civil, podendo existir campo para o nome social, independentemente do registro civil.","ser chamada pelo número do leito, para preservar o sigilo.","ter suas informações divulgadas à imprensa em casos de interesse público, sem autorização.","receber tratamento sem qualquer informação sobre riscos.","ser atendida exclusivamente por ordem de chegada."]'::jsonb, 0, 'A Carta assegura identificação pelo nome, uso do nome social e vedação de identificação por número, código ou doença.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-117', 'sus', null, 'Em um município, o Conselho Municipal de Saúde deliberou sobre a reorganização da rede de Atenção Básica, mas a resolução não foi publicada pelo prefeito. De acordo com a Lei nº 8.142/1990, é correto afirmar que:', '["as decisões do Conselho de Saúde são homologadas pelo chefe do poder legalmente constituído em cada esfera de governo.","as decisões do Conselho dispensam homologação e entram em vigor automaticamente.","o Conselho tem caráter apenas consultivo, e suas decisões não precisam ser consideradas.","a homologação cabe ao Ministério Público.","as decisões do Conselho só valem após aprovação da Conferência Nacional."]'::jsonb, 0, 'Art. 1º, §2º, da Lei 8.142/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-118', 'sus', null, 'Durante a elaboração do plano municipal de saúde, a equipe técnica analisou dados de morbimortalidade para definir prioridades e alocar recursos. Essa prática corresponde ao princípio do SUS que prevê:', '["a utilização da epidemiologia para o estabelecimento de prioridades, a alocação de recursos e a orientação programática.","a universalidade de acesso em todos os níveis.","a preservação da autonomia das pessoas.","a participação da comunidade.","a igualdade da assistência sem preconceitos."]'::jsonb, 0, 'Art. 7º, VII, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-119', 'sus', null, 'Dois municípios vizinhos decidem unir esforços para manter um centro de especialidades que atenderá as duas populações. A Lei nº 8.080/1990 prevê que, para desenvolver em conjunto as ações e os serviços de saúde que lhes correspondam, os Municípios poderão:', '["constituir consórcios, aplicando-se a eles o princípio da direção única.","transferir a gestão do serviço ao Estado, obrigatoriamente.","contratar uma operadora de plano de saúde para administrar o serviço.","solicitar autorização prévia ao Conselho Nacional de Saúde.","criar uma nova esfera de governo com direção própria."]'::jsonb, 0, 'Art. 10 da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-120', 'sus', null, 'Um gestor municipal pretende contratar um hospital privado para complementar a oferta de leitos. Segundo a legislação do SUS, nessa contratação devem ter preferência:', '["as entidades filantrópicas e as sem fins lucrativos.","as empresas de capital estrangeiro.","os hospitais com maior lucro anual.","as empresas de propriedade de servidores públicos.","os hospitais localizados em outros estados."]'::jsonb, 0, 'CF, art. 199, §1º, e Lei 8.080/90, art. 25.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-121', 'sus', null, 'Uma Região de Saúde precisa pactuar, entre os gestores municipais e o gestor estadual, os aspectos operacionais da rede de urgência regional. Segundo o Decreto nº 7.508/2011, essa pactuação ocorre na:', '["Comissão Intergestores Regional (CIR).","Comissão Intergestores Tripartite (CIT).","Conferência Nacional de Saúde.","Câmara de Vereadores do município-sede.","Agência Nacional de Saúde Suplementar."]'::jsonb, 0, 'A CIR é a instância de pactuação no âmbito da Região de Saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-122', 'sus', null, 'Ao receber um usuário que procurou diretamente o hospital de referência sem encaminhamento, a equipe o orientou sobre o acesso pela atenção primária, sem deixar de avaliar a gravidade do caso. Segundo o Decreto nº 7.508/2011, o acesso universal, igualitário e ordenado às ações e serviços de saúde:', '["se inicia pelas Portas de Entrada do SUS e se completa na rede regionalizada e hierarquizada, de acordo com a complexidade do serviço.","se dá exclusivamente pelos hospitais de referência.","independe de qualquer ordenação ou regulação.","é restrito aos usuários com cartão de plano de saúde.","deve ser autorizado pelo Conselho de Saúde em cada caso."]'::jsonb, 0, 'Art. 8º do Decreto 7.508/2011. A atenção primária ordena o acesso, considerando a gravidade do risco individual e coletivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-123', 'sus', null, 'O Decreto nº 7.508/2011 estabelece que, para ser instituída, a Região de Saúde deve conter, no mínimo, ações e serviços de determinadas áreas. Registre V para as que integram esse mínimo e F para as que não integram.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-124', 'sus', null, 'Um usuário recebe prescrição de um medicamento no ambulatório de um hospital privado não conveniado e procura a farmácia da UBS. Segundo o Decreto nº 7.508/2011, o acesso universal e igualitário à assistência farmacêutica pressupõe, entre outros requisitos:', '["que o usuário esteja assistido por ações e serviços de saúde do SUS e que a prescrição tenha sido feita por profissional no exercício regular de suas funções no SUS.","apenas a apresentação de documento de identidade.","a comprovação de renda inferior a um salário mínimo.","a autorização do Conselho Municipal de Saúde.","que o medicamento seja importado."]'::jsonb, 0, 'Art. 28. Também se exige conformidade com a RENAME e os PCDT e dispensação nas unidades indicadas pela direção do SUS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-125', 'sus', null, 'No contexto do controle social, a participação de usuários, trabalhadores e gestores na avaliação da situação de saúde e na proposição de diretrizes para a política de saúde, a cada quatro anos, ocorre:', '["nas Conferências de Saúde.","nas Comissões Intergestores.","nas reuniões de equipe da UBS.","nos Conselhos de Classe.","nas audiências do Poder Judiciário."]'::jsonb, 0, 'Lei 8.142/90, art. 1º, §1º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-126', 'sus', null, 'A Lei nº 8.080/1990 estabelece que a direção do SUS é única e exercida, no âmbito da União, pelo:', '["Ministério da Saúde.","Conselho Nacional de Saúde.","Ministério do Desenvolvimento Social.","Presidente da República.","Congresso Nacional."]'::jsonb, 0, 'Art. 9º, I. Nos Estados, DF e Municípios: respectivas Secretarias de Saúde ou órgão equivalente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-127', 'sus', null, 'A Lei nº 8.080/1990, ao tratar da organização, da direção e da gestão do SUS, estabelece algumas regras. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-128', 'sus', null, 'Considerando a Lei nº 8.080/1990, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-129', 'sus', null, 'Segundo a Lei nº 8.080/1990, o conjunto de ações e serviços de saúde prestados por órgãos e instituições públicas federais, estaduais e municipais, da administração direta e indireta e das fundações mantidas pelo Poder Público, constitui:', '["o Sistema Único de Saúde (SUS).","a Rede de Atenção às Urgências.","a Agência Nacional de Vigilância Sanitária.","a Seguridade Social.","o Subsistema de Atenção à Saúde Indígena."]'::jsonb, 0, 'Art. 4º da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-130', 'sus', null, 'De acordo com a Lei nº 8.080/1990, a execução de ações de vigilância sanitária, de vigilância epidemiológica e de saúde do trabalhador, bem como de assistência terapêutica integral, inclusive farmacêutica, está:', '["incluída no campo de atuação do SUS.","excluída do campo de atuação do SUS.","restrita à iniciativa privada.","sob responsabilidade exclusiva da previdência social.","condicionada à aprovação do Poder Judiciário."]'::jsonb, 0, 'Art. 6º, I, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-131', 'sus', null, 'Segundo a Lei nº 8.080/1990, a política de recursos humanos na área da saúde deve cumprir o objetivo de:', '["organizar um sistema de formação de recursos humanos em todos os níveis de ensino, inclusive de pós-graduação, além de programas de permanente aperfeiçoamento de pessoal.","restringir a formação de profissionais às universidades privadas.","eliminar os programas de educação continuada.","priorizar a contratação de profissionais estrangeiros.","transferir à previdência a responsabilidade pela formação."]'::jsonb, 0, 'Art. 27, I, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-132', 'sus', null, 'No SUS, os recursos financeiros transferidos pelo Fundo Nacional de Saúde aos Municípios, de forma regular e automática, devem ser:', '["movimentados por meio do Fundo Municipal de Saúde, sob fiscalização do Conselho de Saúde.","depositados na conta pessoal do secretário de saúde.","aplicados livremente pelo prefeito, sem prestação de contas.","repassados a hospitais privados sem contrato.","devolvidos à União ao final de cada mês."]'::jsonb, 0, 'Lei 8.080/90, art. 33, e Lei 8.142/90, art. 4º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-133', 'sus', null, 'A Rede de Atenção às Urgências (RUE), instituída pela Portaria GM/MS nº 1.600/2011, é composta por diferentes pontos de atenção que devem atuar de forma articulada. Sobre os componentes da RUE, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-134', 'sus', null, 'A Política Nacional de Atenção às Urgências foi reformulada pela Portaria nº 1.600/2011, que instituiu a RUE. Considerando as suas diretrizes e componentes, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-135', 'sus', null, 'Segundo a Portaria nº 1.600/2011, o componente da RUE que tem como objetivo ordenar o fluxo assistencial e disponibilizar atendimento precoce e transporte adequado, rápido e resolutivo às vítimas acometidas por agravos à saúde, mediante envio de veículos tripulados por equipe capacitada, é o:', '["SAMU 192 e suas Centrais de Regulação Médica das Urgências.","componente hospitalar.","componente Atenção Domiciliar.","componente Promoção, Prevenção e Vigilância.","componente Atenção Básica."]'::jsonb, 0, 'O SAMU 192 é acessado pelo número 192 e acionado por uma Central de Regulação Médica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-136', 'sus', null, 'Na RUE, a Sala de Estabilização (SE) é definida como:', '["ambiente para estabilização de pacientes críticos e/ou graves, com condições de garantir assistência 24 horas, vinculado a um equipamento de saúde e articulado aos demais pontos da rede.","unidade de internação de longa permanência para pacientes crônicos.","consultório de atendimento eletivo da Atenção Básica.","central telefônica de regulação de leitos.","ambulância de suporte avançado."]'::jsonb, 0, 'A SE estabiliza o paciente até a transferência para o ponto de atenção adequado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-137', 'sus', null, 'A Força Nacional de Saúde do SUS, componente da RUE, tem como objetivo:', '["aglutinar esforços para garantir a integralidade da assistência em situações de risco ou emergenciais para populações com vulnerabilidades específicas e em regiões de difícil acesso.","fiscalizar hospitais privados.","substituir as UPA 24h nos municípios de pequeno porte.","executar ações de segurança pública em hospitais.","realizar o transporte de pacientes eletivos."]'::jsonb, 0, 'Atua em situações de epidemias, desastres e desassistência, quando a capacidade local é superada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-138', 'sus', null, 'A Portaria nº 2.048/2002 aprova o Regulamento Técnico dos Sistemas Estaduais de Urgência e Emergência. Sobre a organização do atendimento pré-hospitalar móvel, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-139', 'sus', null, 'Segundo a Portaria nº 2.048/2002, a ambulância destinada ao transporte inter-hospitalar de pacientes com risco de vida conhecido e ao atendimento pré-hospitalar de pacientes com risco de vida desconhecido, não classificados com potencial de necessitar de intervenção médica no local, é a do tipo:', '["B (Suporte Básico).","A (Transporte).","C (Resgate).","D (Suporte Avançado).","E (Aeronave)."]'::jsonb, 0, 'Tipo A: transporte simples, sem risco de vida; B: suporte básico; C: resgate; D: suporte avançado (UTI móvel); E: aeronave; F: embarcação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-140', 'sus', null, 'A regulação médica das urgências é fundamental no SAMU 192. Sobre a transferência inter-hospitalar de pacientes graves, conforme a Portaria nº 2.048/2002, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-141', 'sus', null, 'No âmbito da regulação médica das urgências, o termo "vaga zero" refere-se:', '["à prerrogativa do médico regulador de encaminhar o paciente ao serviço mais adequado mesmo sem leito disponível, em situação de risco de vida.","à proibição de internação de pacientes sem leito livre.","à alta hospitalar sem acompanhamento.","ao leito reservado exclusivamente para pacientes particulares.","à ausência de ambulâncias no município."]'::jsonb, 0, 'A "vaga zero" garante o acesso imediato em situações de urgência, cabendo ao serviço receptor acolher o paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-142', 'sus', null, 'Na Central de Regulação Médica das Urgências, o profissional responsável pelo atendimento inicial das chamadas, pela identificação do solicitante e pelo registro dos dados básicos, antes da avaliação do médico regulador, é o:', '["Técnico Auxiliar de Regulação Médica (TARM).","Rádio-operador.","Condutor de veículo de urgência.","Enfermeiro intervencionista.","Médico intervencionista."]'::jsonb, 0, 'O TARM atende o chamado e o transfere ao médico regulador; o rádio-operador controla a frota e a comunicação com as equipes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-143', 'sus', null, 'A Portaria GM/MS nº 5.350/2024 instituiu a Rede Alyne, que reestrutura a atenção materna e infantil no SUS em substituição à:', '["Rede Cegonha.","Rede de Atenção Psicossocial.","Rede de Cuidados à Pessoa com Deficiência.","Rede de Atenção às Urgências.","Rede de Atenção à Saúde das Pessoas com Doenças Crônicas."]'::jsonb, 0, 'A Rede Alyne atualiza e amplia as ações da Rede Cegonha, criada em 2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-144', 'sus', null, 'A Rede Alyne recebeu esse nome em homenagem a Alyne Pimentel, mulher negra que morreu em 2002, em decorrência de complicações obstétricas por falhas na assistência. A escolha do nome reforça um dos focos centrais da rede, que é:', '["reduzir a mortalidade materna, com ênfase no enfrentamento das desigualdades étnico-raciais.","ampliar a oferta de cesarianas eletivas.","transferir a atenção ao pré-natal para a rede privada.","restringir o acompanhamento às gestantes de alto risco.","substituir a Atenção Básica pelos ambulatórios especializados."]'::jsonb, 0, 'O caso Alyne levou à condenação do Brasil em um comitê da ONU; a rede enfatiza a redução da mortalidade materna, especialmente entre mulheres negras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
